CREATE TABLE IF NOT EXISTS employee_master_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid UNIQUE NOT NULL, employee_number text UNIQUE, legal_name text NOT NULL, preferred_name text, job_title text, department text, employment_type text DEFAULT 'Full-time', employment_status text DEFAULT 'Active', hire_date date, reporting_manager text, work_email text, phone text, location text, probation_end_date date, exit_date date, exit_reason text, emergency_contact_name text, emergency_contact_phone text, notes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS employee_master_department_idx ON employee_master_records(department);
CREATE INDEX IF NOT EXISTS employee_master_status_idx ON employee_master_records(employment_status);